inline float tl_pipeline_float(const void* pipeline, std::uint32_t offset) noexcept {
    float value;
    std::memcpy(&value, static_cast<const std::uint8_t*>(pipeline) + offset, sizeof(value));
    return value;
}

inline bool tl_particle_slots_match(const TlModuleContract& c, std::uintptr_t base,
                                   std::uintptr_t clip, std::uintptr_t particles) noexcept {
    return clip == base + c.set_clip && particles == base + c.transform_particles;
}

inline bool tl_fog_slots_match(const TlModuleContract& c, std::uintptr_t base,
                              std::uintptr_t set, std::uintptr_t apply) noexcept {
    return set == base + c.set_fog && apply == base + c.apply_fog;
}

